@CrossOrigin
@RestController
@RequestMapping("/ClinicianQuery")
public class ClinicianQueryRestController extends BaseSpringRestController {
	
	public ClinicianQueryRestController( ClinicianService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Clinician using a UUID
     * @param		UUID clinicianId
     * @return		Clinician
     */    
    @GetMapping("/load")
    public Clinician load( @RequestParam(required=true) UUID clinicianId ) {
    	Clinician entity = null;

    	try {  
    		entity = service.getClinician( new ClinicianFetchOneSummary( clinicianId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Clinician using Id " + clinicianId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Clinician business objects
     * @return		Set<Clinician>
     */
    @GetMapping("/")
    public List<Clinician> loadAll() {                
    	List<Clinician> clinicianList = null;
        
    	try {
            // load the Clinician
            clinicianList = service.getAllClinician();
            
            if ( clinicianList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Clinicians" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Clinicians ", exc );
        	return null;
        }

        return clinicianList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Clinician clinician = null;
    protected ClinicianService service = null;
    private static final Logger LOGGER = Logger.getLogger(ClinicianQueryRestController.class.getName());
    
}
